content.rust:
// Environnement déclaré en premier. Toujours.
pub const SYSTEM:  &str = "Alchem";
pub const VERSION: &str = "1.0.0";

#[derive(Debug, Clone)]
pub struct Env {
    pub system:  &'static str,
    pub version: &'static str,
}

pub const ENV: Env = Env { system: SYSTEM, version: VERSION };
